'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent, type ReactNode } from 'react';
import { cssEase, useStudioMotion, type EasingToken } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { mode: string; duration: number; easing: string; icon: string; defaultOpen: number; look: string };

/** Sample content for an invented print studio. */
const ITEMS: readonly { id: string; q: string; a: ReactNode }[] = [
  { id: 'book', q: 'How do bookings work?', a: <p>Book a two- or four-hour bench online or at the desk. Every bench comes with a drying rack, a set of rollers and a check-in from a technician at the start of your slot.</p> },
  { id: 'paper', q: 'Can I bring my own paper?', a: <><p>Yes. Most papers up to 300 gsm run through the proofing press without trouble.</p><p>Bring two spare sheets for a test print; heavily textured stock may need a softer packing, which the technician can set up for you.</p></> },
  { id: 'cancel', q: 'What if I need to cancel?', a: <p>Cancel up to 24 hours ahead for a full credit. After that you can hand the slot to someone else by telling the desk their name.</p> },
  { id: 'access', q: 'Is the studio step-free?', a: <><p>The ground floor, the main press and the accessible toilet are step-free. The darkroom is up six steps:</p><ul><li>ask at the desk and a technician will bring exposures down to you,</li><li>or book the ground-floor light table instead,</li><li>large-print and screen-reader friendly safety notes are on the website.</li></ul></> },
  { id: 'classes', q: 'Do you run classes for beginners?', a: <p>Twice a month: a Saturday morning introduction to relief printing and a Thursday evening session on screen printing. Materials are included and no experience is needed.</p> },
];
const EASINGS: readonly EasingToken[] = ['emphasized', 'standard', 'inOut', 'enter'];

export default function AccordionHeightAuto({ params }: EffectProps<Params>) {
  const { reduced, scale } = useStudioMotion();
  const uid = useId();
  const single = params.mode !== 'multiple';
  const initial = () => (params.defaultOpen >= 1 && params.defaultOpen <= ITEMS.length ? [ITEMS[params.defaultOpen - 1].id] : []);
  const [open, setOpen] = useState<string[]>(initial);
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);

  // Param changes restart from the configured state.
  useEffect(() => { setOpen(initial()); }, [params.defaultOpen, single]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggle = (id: string) => setOpen((cur) => {
    if (cur.includes(id)) return cur.filter((x) => x !== id);
    return single ? [id] : [...cur, id];
  });
  const onKeyDown = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
    const last = ITEMS.length - 1;
    const to = e.key === 'ArrowDown' ? (i === last ? 0 : i + 1) : e.key === 'ArrowUp' ? (i === 0 ? last : i - 1) : e.key === 'Home' ? 0 : e.key === 'End' ? last : null;
    if (to === null) return;
    e.preventDefault();
    buttons.current[to]?.focus();
  };

  const ease = EASINGS.includes(params.easing as EasingToken) ? (params.easing as EasingToken) : 'emphasized';
  return (
    <div
      className={styles.root}
      data-look={params.look === 'cards' ? 'cards' : 'hairline'}
      data-icon={params.icon === 'plus' ? 'plus' : 'chevron'}
      data-reduced={reduced || undefined}
      style={{ '--acc-dur': `${Math.round(params.duration * scale.duration)}ms`, '--acc-ease': cssEase(ease) } as CSSProperties}
    >
      <header className={styles.head}>
        <p className={styles.eyebrow}>Halden Print Room · help</p>
        <h3 className={styles.title}>Visiting the print room</h3>
        <p className={styles.note}>Sample content · {single ? 'one answer open at a time' : 'open as many as you like'}</p>
      </header>
      <div className={styles.group}>
        {ITEMS.map((item, i) => {
          const isOpen = open.includes(item.id);
          return (
            <div key={item.id} className={styles.item} data-open={isOpen || undefined}>
              <h4 className={styles.heading}>
                <button
                  ref={(el) => { buttons.current[i] = el; }}
                  id={`${uid}b${i}`}
                  type="button"
                  className={styles.trigger}
                  aria-expanded={isOpen}
                  aria-controls={`${uid}p${i}`}
                  onClick={() => toggle(item.id)}
                  onKeyDown={(e) => onKeyDown(e, i)}
                >
                  <span className={styles.index} aria-hidden="true">{String(i + 1).padStart(2, '0')}</span>
                  <span className={styles.question}>{item.q}</span>
                  <span className={styles.icon} aria-hidden="true"><i /><i /></span>
                </button>
              </h4>
              <div id={`${uid}p${i}`} role="region" aria-labelledby={`${uid}b${i}`} className={styles.panel}>
                <div className={styles.inner}>
                  <div className={styles.content}>{item.a}</div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

.root {
  --acc-dur: 360ms;
  --acc-ease: cubic-bezier(0.16, 1, 0.3, 1);
  container-type: inline-size;
  box-sizing: border-box;
  width: min(100% - 2rem, 40rem);
  margin: clamp(1rem, 3cqi, 2rem) auto;
  display: grid;
  gap: 1rem;
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}
.head { display: grid; gap: 0.4rem; }
.eyebrow, .note, .index {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--mk-ink-muted, #5c5a52);
}
.title {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.5rem, 5.5cqi, 2.25rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.035em;
}

/* ── Items ────────────────────────────────────────────────────────────── */
.group { display: grid; }
.root[data-look='hairline'] .group { border-top: 1px solid var(--mk-line-strong, #11110f); }
.root[data-look='hairline'] .item { border-bottom: 1px solid var(--mk-line, #11110f24); }
.root[data-look='cards'] .group { gap: 8px; }
.root[data-look='cards'] .item {
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-m, 10px);
  background: var(--mk-surface-2, #e9e5da);
  transition: background-color var(--acc-dur) var(--acc-ease);
}
.root[data-look='cards'] .item[data-open] { background: var(--mk-bg, #f3f0e8); }
.heading { margin: 0; }
.trigger {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr) 24px;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  min-height: 56px;
  padding: 0.85rem 0.25rem;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
}
.root[data-look='cards'] .trigger { padding-inline: 0.9rem; }
.trigger:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: -2px; border-radius: 6px; }
.question {
  font-size: clamp(1rem, 3cqi, 1.125rem);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.015em;
  text-wrap: balance;
}
.trigger:hover .question { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.2em; }

/* Icon: two bars drawn as a chevron (V) or a plus; both states animate with the same token. */
.icon { position: relative; justify-self: center; width: 14px; height: 14px; transition: rotate var(--acc-dur) var(--acc-ease); }
.icon i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 8.5px;
  height: 1.75px;
  border-radius: 1px;
  background: currentColor;
  transition: transform var(--acc-dur) var(--acc-ease);
}
.root[data-icon='chevron'] .icon i:first-child { transform: translate(-88%, -50%) rotate(45deg); }
.root[data-icon='chevron'] .icon i:last-child { transform: translate(-12%, -50%) rotate(-45deg); }
.root[data-icon='chevron'] .item[data-open] .icon { rotate: 180deg; }
.root[data-icon='plus'] .icon i { width: 13px; }
.root[data-icon='plus'] .icon i:first-child { transform: translate(-50%, -50%); }
.root[data-icon='plus'] .icon i:last-child { transform: translate(-50%, -50%) rotate(90deg); }
.root[data-icon='plus'] .item[data-open] .icon i:last-child { transform: translate(-50%, -50%) rotate(180deg); }

/* ── Height: auto via grid tracks ─────────────────────────────────────── */
.panel {
  display: grid;
  grid-template-rows: 0fr;
  visibility: hidden;
  /* stay visible until the collapse has finished, then leave the tab order and accessibility tree */
  transition: grid-template-rows var(--acc-dur) var(--acc-ease), visibility 0s linear var(--acc-dur);
}
.item[data-open] .panel {
  grid-template-rows: 1fr;
  visibility: visible;
  transition: grid-template-rows var(--acc-dur) var(--acc-ease), visibility 0s;
}
.inner { min-height: 0; overflow: hidden; }
.content {
  padding: 0 0.25rem 1.25rem calc(2rem + 0.75rem + 0.25rem);
  font-size: 0.9375rem;
  line-height: 1.55;
  color: var(--mk-ink, #11110f);
  opacity: 0;
  translate: 0 -6px;
  transition: opacity calc(var(--acc-dur) * 0.5) linear, translate var(--acc-dur) var(--acc-ease);
}
.root[data-look='cards'] .content { padding-inline-end: 1rem; }
.item[data-open] .content {
  opacity: 1;
  translate: 0 0;
  transition: opacity calc(var(--acc-dur) * 0.7) linear calc(var(--acc-dur) * 0.15), translate var(--acc-dur) var(--acc-ease);
}
.content p { margin: 0 0 0.6rem; max-width: 56ch; text-wrap: pretty; }
.content p:last-child { margin-bottom: 0; }
.content ul { margin: 0.25rem 0 0; padding-left: 1.1rem; list-style: disc; display: grid; gap: 0.3rem; max-width: 54ch; }
.content li::marker { color: var(--mk-ink-muted, #5c5a52); }

@container (max-width: 420px) {
  .trigger { grid-template-columns: 1.6rem minmax(0, 1fr) 24px; gap: 0.5rem; }
  .content { padding-left: calc(1.6rem + 0.5rem + 0.25rem); }
}

/* Tier 2: no height or icon travel; new content fades in. */
.root[data-reduced] .panel, .root[data-reduced] .item[data-open] .panel { transition: none; }
.root[data-reduced] .icon, .root[data-reduced] .icon i, .root[data-reduced] .item { transition: none; }
.root[data-reduced] .content { translate: none; transition: none; }
.root[data-reduced] .item[data-open] .content { transition: opacity 160ms linear; }
@media (prefers-reduced-motion: reduce) {
  .panel, .item[data-open] .panel, .icon, .icon i { transition: none; }
  .content { translate: none; transition: none; }
  .item[data-open] .content { transition: opacity 160ms linear; }
}
